package com.tekwatt.reporting.service;import static org.assertj.core.api.Assertions.assertThat;import com.fasterxml.jackson.databind.ObjectMapper;import com.tekwatt.reporting.entity.ReportType;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;class CsvReportGeneratorTests{@Test void createsDailyCsvAndEscapesValues()throws Exception{var generator=new CsvReportGenerator(new ObjectMapper());var data=new ObjectMapper().readTree("[{\"date\":\"2026-08-01\",\"sessions\":2,\"note\":\"A,B\"}]");String result=new String(generator.generate(ReportType.DAILY,data),StandardCharsets.UTF_8);assertThat(result).isEqualTo("date,sessions,note\n2026-08-01,2,\"A,B\"\n");}}
